import sys
lines = sys.stdin.read().splitlines()
if lines:
    parts = lines[0].split()
    n, k = int(parts[0]), int(parts[1])
    pts = []
    for line in lines[1:1+n]:
        xy = [int(v) for v in line.split()]
        if len(xy) == 2: pts.append(xy)
    pts.sort(key=lambda p: (p[0]**2 + p[1]**2, p[0], p[1]))
    for p in pts[:k]:
        print(f'{p[0]} {p[1]}')
